const results = $input.all();
const experiments = {};
results.forEach(r => {
  if (!experiments[r.json.experiment_id]) experiments[r.json.experiment_id] = [];
  experiments[r.json.experiment_id].push({variant: r.json.variant, users: r.json.users, conversions: r.json.conversions, conversion_rate: (r.json.conversions / r.json.users * 100).toFixed(2)});
});
return Object.entries(experiments).map(([expId, variants]) => ({json: {experiment_id: expId, variants: variants, winner: variants.reduce((max, v) => parseFloat(v.conversion_rate) > parseFloat(max.conversion_rate) ? v : max, variants[0])}}));
